class Document:
    def __init__(self, path, content, metadata=None):
        self.path = path
        self.content = content
        self.metadata = metadata if metadata else {}

from models import Document

class KnowledgeBaseLogic:
    def __init__(self, storage):
        self.storage = storage

    def ingest_document(self, path):
        content = self.storage.read_file(path)
        return Document(path, content)

    def search_documents(self, query, metadata_filter=None):
        documents = self.storage.list_documents()
        results = []
        for doc in documents:
            if query.lower() in doc.content.lower():
                if metadata_filter is None or all(doc.metadata.get(key, None) == value for key, value in metadata_filter.items()):
                    results.append(doc)
        return results

import os
class KnowledgeBaseStorage:
    def __init__(self, base_path):
        self.base_path = base_path

    def read_file(self, path):
        with open(os.path.join(self.base_path, path), 'r') as file:
            return file.read()

    def list_documents(self):
        documents = []
        for root, _, files in os.walk(self.base_path):
            for file in files:
                if file.endswith('.md'):
                    documents.append(Document(os.path.join(root, file), self.read_file(os.path.join(root, file))))
        return documents

import argparse
from logic import KnowledgeBaseLogic
def main(args=None):
    parser = argparse.ArgumentParser(description="Local Knowledge Base")
    parser.add_argument("command", choices=["ingest", "search"], help="Command to run")
    parser.add_argument("path", nargs='?', help="Path to document for ingestion")
    parser.add_argument("--query", help="Search query")
    parser.add_argument("--filter", nargs='*', action='append', metavar=('key', 'value'), help="Metadata filter")
    args = parser.parse_args(args)

    storage = KnowledgeBaseStorage('knowledge-base')
    logic = KnowledgeBaseLogic(storage)

    if args.command == "ingest":
        if args.path:
            logic.ingest_document(args.path)
            print(f"Ingested {args.path}")
        else:
            print("Please provide a path to ingest.")
    elif args.command == "search":
        if args.query:
            results = logic.search_documents(args.query, metadata_filter=args.filter)
            for result in results:
                print(f"Found in {result.path}")
        else:
            print("Please provide a search query.")

if __name__ == "__main__":
    main()

